contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Deposit ether into c, which increases both the caller's credit and c's balance.
        c.deposit{value: depositAmount}();

        // Read the state before withdrawAll.
        uint creditBefore = c.credit(address(this));
        uint balanceBefore = address(c).balance;

        // Attempt to withdraw all credited ether.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the state after withdrawAll.
        uint creditAfter = c.credit(address(this));
        uint balanceAfter = address(c).balance;

        // The rule: (new credit) + (new contract balance) == (old contract balance).
        // This holds whether the call reverts or succeeds.
        assert(creditAfter + balanceAfter == balanceBefore);
    }

    receive() external payable {}
}

